def match(orders):
    trades = []

    # Resting orders: lists of [id, side, price, qty, arrival_time]
    # For buys: sorted by price descending, then arrival_time ascending
    # For sells: sorted by price ascending, then arrival_time ascending
    buy_orders = []  # max heap by price, then min by arrival_time
    sell_orders = []  # min heap by price, then min by arrival_time

    # Track order status: id -> (side, price, qty_filled)
    order_status = {}  # id -> {'side': side, 'price': price, 'qty_filled': qty}

    for arrival_time, order in enumerate(orders):
        if order[0] == 'cancel':
            order_id = order[1]
            # Remove from resting orders if present
            if order_id in order_status:
                status = order_status[order_id]
                qty_filled = status['qty_filled']
                original_qty = status.get('original_qty', 0)
                # Only cancel if not fully filled
                if qty_filled < original_qty:
                    side = status['side']
                    if side == 'buy':
                        buy_orders[:] = [o for o in buy_orders if o[0] != order_id]
                    else:
                        sell_orders[:] = [o for o in sell_orders if o[0] != order_id]
                del order_status[order_id]

